/**
 * The purchase gate (docs/03-purchase-flow.md). Redis runs a script to completion without running
 * any other command in between, so the checks and the writes below are one atomic step: two
 * buyers can never both take the last unit, and one buyer can never take two. A losing attempt
 * only reads; only winners write.
 *
 * KEYS[1]  sale hash    startsAt, endsAt, remainingStock, paused (during recovery only)
 * KEYS[2]  buyers hash  userId -> {"orderId", "purchasedAt"}
 * ARGV[1]  normalised user ID
 * ARGV[2]  order ID generated by the API
 */
export const RESERVE_SCRIPT = `
local sale = redis.call('HMGET', KEYS[1], 'startsAt', 'endsAt', 'remainingStock', 'paused')
if not sale[1] then
  return { 'not_initialized' }
end

-- Rule 0: the recovery job is rebuilding the state.
if sale[4] then
  return { 'paused' }
end

-- Rule 1, checked before the others so that retries are safe: a buyer always gets their
-- original order back.
local existing = redis.call('HGET', KEYS[2], ARGV[1])
if existing then
  return { 'already_purchased', existing }
end

-- Rules 2 and 3 use Redis's clock, the same for every API server.
local time = redis.call('TIME')
local now = tonumber(time[1]) * 1000 + math.floor(tonumber(time[2]) / 1000)
if now < tonumber(sale[1]) then
  return { 'not_started' }
end
if now >= tonumber(sale[2]) then
  return { 'ended' }
end

-- Rule 4.
if tonumber(sale[3]) <= 0 then
  return { 'sold_out' }
end

-- Rule 5: take one unit and record the buyer.
local order = cjson.encode({ orderId = ARGV[2], purchasedAt = now })
redis.call('HINCRBY', KEYS[1], 'remainingStock', -1)
redis.call('HSET', KEYS[2], ARGV[1], order)
return { 'reserved', order }
`;

export type ReserveScriptReply = [
  result:
    | 'reserved'
    | 'already_purchased'
    | 'paused'
    | 'not_started'
    | 'ended'
    | 'sold_out'
    | 'not_initialized',
  buyerRecord?: string,
];
